script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var canvas = document.getElementById('analysisCanvas');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnTakeReading = document.getElementById('btnTakeReading');
  var btnSaveBaseline = document.getElementById('btnSaveBaseline');
  var btnSaveDimmed = document.getElementById('btnSaveDimmed');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var noiseFill = document.getElementById('noiseFill');
  var noiseLabel = document.getElementById('noiseLabel');
  var statNoiseScore = document.getElementById('statNoiseScore');
  var statBaseline = document.getElementById('statBaseline');
  var statDimmed = document.getElementById('statDimmed');
  var statSnr = document.getElementById('statSnr');
  var statVerdict = document.getElementById('statVerdict');
  var statMean = document.getElementById('statMean');
  var statEstimated = document.getElementById('statEstimated');
  var statSigma = document.getElementById('statSigma');
  var statRatio = document.getElementById('statRatio');
  var statNoisePct = document.getElementById('statNoisePct');
  var statNeeded = document.getElementById('statNeeded');
  var statFps = document.getElementById('statFps');
  var statResolution = document.getElementById('statResolution');
  var statMegapixels = document.getElementById('statMegapixels');
  var statAspect = document.getElementById('statAspect');
  var statAvgRgb = document.getElementById('statAvgRgb');
  var statLightness = document.getElementById('statLightness');
  var statLuminosity = document.getElementById('statLuminosity');
  var statHue = document.getElementById('statHue');
  var statSaturation = document.getElementById('statSaturation');
  var statWebcam = document.getElementById('statWebcam');
  var nativeCanvas = document.createElement('canvas');
  var NATIVE_SIZE = 64;
  var readingTimer = null;
  var ratedFps = 0;
  var frameCount = 0;
  var fpsLoopId = null;

  var currentStream = null;
  var starting = false;
  var reading = false;
  var lastScore = null;
  var SAMPLE_SIZE = 32;
  var SAMPLE_COUNT = 20;
  var SAMPLE_INTERVAL_MS = 70;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  // Same stopStream()/describeError()/populateDeviceSelect() pattern as
  // webcam-test-online's own script (see this project's CLAUDE.md -- every
  // camera tool copies this teardown block rather than importing a shared file).
  function stopStream() {
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnTakeReading.disabled = true;
    if (readingTimer) { clearInterval(readingTimer); readingTimer = null; }
    reading = false;
    if (fpsLoopId !== null && video.cancelVideoFrameCallback) video.cancelVideoFrameCallback(fpsLoopId);
    fpsLoopId = null;
    noiseFill.style.width = '0%';
    noiseLabel.textContent = '—';
    statNoiseScore.textContent = '—';
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a webcam and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try another camera from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  function classify(score) {
    if (score < 12) return 'Very Clean';
    if (score < 28) return 'Clean';
    if (score < 50) return 'Moderate';
    if (score < 75) return 'Noisy';
    return 'Very Noisy';
  }

  function sampleFrame() {
    var w = video.videoWidth, h = video.videoHeight;
    if (!w || !h) return null;
    canvas.width = SAMPLE_SIZE;
    canvas.height = SAMPLE_SIZE;
    var ctx = canvas.getContext('2d');
    // Sample a small fixed crop from the centre of the frame -- the same
    // region every time, since temporal variance only measures noise
    // correctly when comparing the identical patch of scene across frames.
    var cropSize = Math.min(w, h) * 0.3;
    var sx = (w - cropSize) / 2, sy = (h - cropSize) / 2;
    ctx.drawImage(video, sx, sy, cropSize, cropSize, 0, 0, SAMPLE_SIZE, SAMPLE_SIZE);
    try {
      var data = ctx.getImageData(0, 0, SAMPLE_SIZE, SAMPLE_SIZE).data;
      var gray = new Float32Array(SAMPLE_SIZE * SAMPLE_SIZE);
      for (var i = 0, p = 0; i < data.length; i += 4, p++) {
        gray[p] = data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114;
      }
      return gray;
    } catch (e) {
      return null;
    }
  }

  // Temporal variance (the same pixel position across consecutive frames
  // of a held-still scene), not spatial variance -- spatial variance can't
  // distinguish noise from real fine detail in the scene, per this tool's
  // own spec note. Timer-driven (not requestAnimationFrame) since this is
  // a background sampling task, not rendering.
  function takeReading() {
    if (!currentStream || reading) return;
    reading = true;
    btnTakeReading.disabled = true;
    btnSaveBaseline.disabled = true;
    btnSaveDimmed.disabled = true;
    setDiagnostic([{ sev: '', html: 'Reading… hold the camera and scene completely still.' }]);

    var frames = [];
    var natives = [];
    var count = 0;
    var t0 = performance.now(), f0 = frameCount;
    readingTimer = setInterval(function () {
      var g = sampleFrame();
      if (g) frames.push(g);
      var nat = sampleNative();
      if (nat) natives.push(nat);
      count++;
      if (count >= SAMPLE_COUNT) {
        clearInterval(readingTimer);
        readingTimer = null;
        var secs = (performance.now() - t0) / 1000;
        finishReading(frames);
        finishSnr(natives, video.requestVideoFrameCallback && secs > 0 ? (frameCount - f0) / secs : 0);
      }
    }, SAMPLE_INTERVAL_MS);
  }

  // Counts frames actually delivered by the camera (for the measured fps).
  function countFrames() {
    if (!currentStream) return;
    frameCount++;
    fpsLoopId = video.requestVideoFrameCallback(countFrames);
  }

  // Full-resolution 64x64 centre patch (no downscaling, which would average
  // the noise away) plus its average RGB, for the SNR measurement.
  function sampleNative() {
    var w = video.videoWidth, h = video.videoHeight;
    if (!w || !h) return null;
    var size = Math.min(NATIVE_SIZE, w, h);
    nativeCanvas.width = size;
    nativeCanvas.height = size;
    var nctx = nativeCanvas.getContext('2d');
    nctx.drawImage(video, Math.round((w - size) / 2), Math.round((h - size) / 2), size, size, 0, 0, size, size);
    try {
      var data = nctx.getImageData(0, 0, size, size).data;
      var gray = new Float32Array(size * size);
      var r = 0, g = 0, b = 0;
      for (var i = 0, p = 0; i < data.length; i += 4, p++) {
        r += data[i]; g += data[i + 1]; b += data[i + 2];
        gray[p] = data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114;
      }
      var n = size * size;
      return { gray: gray, r: r / n, g: g / n, b: b / n };
    } catch (e) {
      return null;
    }
  }

  function f1(v) { return (Math.round(v * 10) / 10).toFixed(1); }
  function f2(v) { return (Math.round(v * 100) / 100).toFixed(2); }

  // Signal = mean Rec. 601 luma of the patch's average RGB; noise sigma =
  // std(F1 - F2) / sqrt(2) averaged over consecutive frame pairs (identical
  // pairs, where the timer fired twice on one camera frame, are skipped).
  function finishSnr(natives, measuredFps) {
    if (natives.length < 3) return;
    var r = 0, g = 0, b = 0;
    natives.forEach(function (s) { r += s.r; g += s.g; b += s.b; });
    r /= natives.length; g /= natives.length; b /= natives.length;
    var diffs = [];
    for (var k = 1; k < natives.length; k++) {
      var a = natives[k - 1].gray, c = natives[k].gray, s1 = 0, s2 = 0, same = true;
      for (var i = 0; i < a.length; i++) { var d = c[i] - a[i]; if (d !== 0) same = false; s1 += d; s2 += d * d; }
      if (same) continue;
      var m = s1 / a.length;
      diffs.push(Math.sqrt(Math.max(0, s2 / a.length - m * m)));
    }
    var mean = 0.299 * r + 0.587 * g + 0.114 * b;
    statMean.textContent = f1(mean) + ' / 255';
    statEstimated.textContent = Math.round(mean / 255 * 100) + ' / 100';
    var sigma = diffs.length ? diffs.reduce(function (x, y) { return x + y; }, 0) / diffs.length / Math.SQRT2 : 0;
    if (!(sigma > 0) || !(mean > 0)) {
      statSnr.textContent = mean > 0 ? 'No noise measured' : 'Picture is black';
      statVerdict.textContent = mean > 0 ? 'No frame-to-frame change detected' : 'No signal: check the lens cover';
      [statSigma, statRatio, statNoisePct, statNeeded].forEach(function (el) { el.textContent = '—'; });
    } else {
      var ratio = mean / sigma;
      var snr = 20 * Math.log10(ratio);
      statSnr.textContent = f1(snr) + ' dB';
      statVerdict.textContent = snr < 20 ? 'Heavy grain: too dark, add light first'
        : snr < 28 ? 'Visible grain in shadows: usable, fix if you can'
        : snr <= 34 ? 'Call-ready: clean face, slight grain in dark corners' : 'Very clean: no visible grain';
      statSigma.textContent = f2(sigma);
      statRatio.textContent = f1(ratio) + ' : 1';
      statNoisePct.textContent = f2(sigma / 255 * 100) + '%';
      var need = sigma * Math.pow(10, 28 / 20);
      statNeeded.textContent = need > 255 ? 'Above 255: lower the noise' : f1(need) + ' / 255';
    }
    if (ratedFps && measuredFps) {
      statFps.textContent = f1(measuredFps) + ' of ' + f1(ratedFps) + ' fps' + (measuredFps < ratedFps * 0.9 ? ' (dropped: longer exposure)' : '');
    } else if (measuredFps || ratedFps) {
      statFps.textContent = f1(measuredFps || ratedFps) + ' fps';
    }
    var rn = r / 255, gn = g / 255, bn = b / 255;
    var mx = Math.max(rn, gn, bn), mn = Math.min(rn, gn, bn), l = (mx + mn) / 2, hue = 0, sat = 0;
    if (mx !== mn) {
      var dd = mx - mn;
      sat = l > 0.5 ? dd / (2 - mx - mn) : dd / (mx + mn);
      if (mx === rn) hue = ((gn - bn) / dd + (gn < bn ? 6 : 0)) * 60;
      else if (mx === gn) hue = ((bn - rn) / dd + 2) * 60;
      else hue = ((rn - gn) / dd + 4) * 60;
    }
    statAvgRgb.textContent = 'rgb(' + Math.round(r) + ', ' + Math.round(g) + ', ' + Math.round(b) + ')';
    statLightness.textContent = f1(l * 100) + '%';
    statLuminosity.textContent = f1((0.2126 * r + 0.7152 * g + 0.0722 * b) / 255 * 100) + '%';
    statHue.textContent = mx === mn ? '—' : Math.round(hue) + '°';
    statSaturation.textContent = f1(sat * 100) + '%';
  }

  function gcd(a, b) { return b ? gcd(b, a % b) : a; }

  function finishReading(frames) {
    reading = false;
    btnTakeReading.disabled = false;
    btnSaveBaseline.disabled = false;
    btnSaveDimmed.disabled = false;

    if (frames.length < 4) {
      setDiagnostic([{ sev: 'warn', html: 'Could not get enough samples for a reading -- try again.' }]);
      return;
    }

    var pixelCount = frames[0].length;
    var varianceSum = 0;
    for (var p = 0; p < pixelCount; p++) {
      var sum = 0;
      for (var f = 0; f < frames.length; f++) sum += frames[f][p];
      var mean = sum / frames.length;
      var sq = 0;
      for (var f2 = 0; f2 < frames.length; f2++) {
        var d = frames[f2][p] - mean;
        sq += d * d;
      }
      varianceSum += sq / frames.length;
    }
    var avgVariance = varianceSum / pixelCount;

    // Scaling divisor is empirical, not a calibrated absolute unit -- see
    // this tool's own field-note. Tuned against real hardware during
    // this build so a typical well-lit reading lands well short of 100,
    // leaving headroom to show the score rise as light drops.
    var score = Math.max(0, Math.min(100, Math.round(avgVariance / 1.2)));

    lastScore = score;
    noiseFill.style.width = score + '%';
    noiseLabel.textContent = score + ' — ' + classify(score);
    statNoiseScore.textContent = String(score);
    setDiagnostic([{ sev: 'ok', html: '<strong>Reading complete: ' + score + ' (' + classify(score) + ').</strong> Save this as your normal-light or dimmed comparison below, or take another reading.' }]);
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    navigator.mediaDevices.getUserMedia({ video: deviceId ? { deviceId: { exact: deviceId } } : true, audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        var w = settings.width || video.videoWidth, h = settings.height || video.videoHeight;
        statWebcam.textContent = track.label || 'Not named';
        statResolution.textContent = w && h ? w + ' × ' + h : '—';
        statMegapixels.textContent = w && h ? f2(w * h / 1e6) + ' MP' : '—';
        statAspect.textContent = w && h ? (w / gcd(w, h)) + ':' + (h / gcd(w, h)) : '—';
        ratedFps = settings.frameRate || 0;
        if (video.requestVideoFrameCallback) fpsLoopId = video.requestVideoFrameCallback(countFrames);
        btnStop.disabled = false;
        btnTakeReading.disabled = false;
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> Let it settle for a couple of seconds after any light change, then click Take a Reading and hold still.' }]);
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });
  btnTakeReading.addEventListener('click', takeReading);
  btnSaveBaseline.addEventListener('click', function () {
    if (lastScore === null) return;
    statBaseline.textContent = String(lastScore);
  });
  btnSaveDimmed.addEventListener('click', function () {
    if (lastScore === null) return;
    statDimmed.textContent = String(lastScore);
  });

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnStart.disabled = true;
  }
})();
